// v1 — guard de whitelist + normalización de query.
// Whitelist hardcoded acá como defense in depth. La validación primaria
// vive en el system prompt (modo interno se decide ahí según subscriber_id).
// Si el agente invoca esta tool con un subscriber_id que NO está en la whitelist,
// devuelve ERROR para evitar leaks de precios a leads externos.

const WHITELIST = (process.env.SYS_INTERNAL_SUBSCRIBERS || '').split(',').map(s => s.trim()).filter(Boolean);
// Fallback hardcoded mientras no esté la env var configurada en n8n.
const WHITELIST_FALLBACK = [
  '<<<SUBSCRIBER_ID_EDGARDO>>>',
  '<<<SUBSCRIBER_ID_RODRI>>>',
  '<<<SUBSCRIBER_ID_LA AGENCIA>>>'
];
const allowed = WHITELIST.length > 0 ? WHITELIST : WHITELIST_FALLBACK;

const args = $input.first().json;
const subId = String(args.subscriber_id || '').trim();
const query = String(args.query || '').trim();
const sessionId = String(args.session_id || '').trim() || 'unknown';

if (!query) {
  return [{ json: { _skip: true, _reason: 'empty_query', status: 'ERROR', message_to_agent: 'Faltó el término de búsqueda. Pedí un modelo, marca o tecnología específica.' } }];
}

if (!subId || !allowed.includes(subId)) {
  return [{ json: { _skip: true, _reason: 'not_whitelisted', status: 'ERROR', message_to_agent: 'Esta consulta es solo para uso interno del equipo. No puedo compartir precios por este canal — un comercial te va a contactar para pasarte el detalle.' } }];
}

// Normalizar query: minúsculas, sin acentos, sin caracteres no alfanuméricos extras
const normalized = query
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9 ]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const keywords = normalized.split(' ').filter(k => k.length >= 2);

return [{ json: { _skip: false, query, normalized, keywords, session_id: sessionId, subscriber_id: subId } }];

// Filtra filas por matching de keywords contra TODAS las columnas concatenadas.
// No asume nombres de columna específicos — el sheet de Rodri puede tener
// columnas distintas (modelo, marca, descripcion, precio, etc.) y este nodo
// es robusto a esa variabilidad.

const rows = $input.all();
const ctx = $('Validate + Guard whitelist').first().json;
const keywords = ctx.keywords || [];

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const matches = rows.filter(r => {
  const concatenated = normalize(Object.values(r.json).join(' '));
  // Match: TODAS las keywords aparecen en la fila (AND, no OR — más preciso)
  return keywords.every(k => concatenated.includes(k));
});

if (matches.length === 0) {
  return [{ json: {
    status: 'NOT_FOUND',
    data: { query: ctx.query, keywords, total_rows: rows.length, matches: 0 },
    message_to_agent: `No encontré ningún equipo que matchee "${ctx.query}" en la planilla de precios. Verificá la grafía o probá con menos keywords.`,
    trace_id: $execution.id
  } }];
}

// Cap: máximo 5 matches para no inundar el chat ni el contexto del LLM
const topMatches = matches.slice(0, 5).map(r => r.json);

return [{ json: {
  status: matches.length > 5 ? 'AMBIGUOUS' : 'RESOLVED',
  data: {
    query: ctx.query,
    total_matches: matches.length,
    shown: topMatches.length,
    items: topMatches
  },
  message_to_agent: matches.length > 5
    ? `Encontré ${matches.length} matches para "${ctx.query}". Te paso los primeros 5 — pedile al usuario interno que afine la búsqueda si necesita ver más.`
    : `Encontré ${matches.length} match(es) para "${ctx.query}". Pasale los datos al usuario interno tal cual aparecen en la planilla, sin redondear ni interpretar precios.`,
  trace_id: $execution.id
} }];
